SELECT DATE_FORMAT(last_restock, 'yyyy-MM') AS last_restock_month, store_id, COUNT(quantity) AS quantity_count, MIN(quantity) AS min_quantity, ROUND(AVG(quantity), 2) AS avg_quantity FROM inventory WHERE quantity <> 119 AND product_id IN (2, 5) AND store_id IN (4, 5) GROUP BY last_restock_month, store_id HAVING MIN(quantity) >= 150 ORDER BY min_quantity, store_id DESC, last_restock_month LIMIT 10;
